-- skeptic-g5 (round 2 skeptic, 2026-09-24). Python door, read-only, SELECT/WITH only.
-- Each connection first ran: ALTER SESSION SET STATEMENT_TIMEOUT_IN_SECONDS = 300; ALTER SESSION SET QUERY_TAG = 'skeptic-r2-2026-09-24';
-- Statement count: S1 (schema) + lead 1: 9 + lead 2: 8 (+2 that failed to compile and were re-run: L2-5 had a bad STATE column, L2-6 had an unexpanded id list) + lead 3: 4.
-- Median/bucket math on L2-5 rows ran in Python on the returned rows.

-- [S1] schema of the ICIS-Air tables used
SELECT TABLE_NAME, LISTAGG(COLUMN_NAME || ':' || DATA_TYPE, ', ') WITHIN GROUP (ORDER BY ORDINAL_POSITION) FROM LIBRARY_MARTS.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='ENVIRONMENT' AND TABLE_NAME LIKE 'ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_%' GROUP BY 1;

-- [L1-1] Nebraska formal actions: by agency flag, action type and settlement-date era, including rows with no settlement date
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT a.STATE_EPA_FLAG, a.ENF_TYPE_DESC, a.ACTIVITY_TYPE_DESC,
  CASE WHEN a.SETTLEMENT_ENTERED_DATE IS NULL THEN 'NO DATE' WHEN a.SETTLEMENT_ENTERED_DATE < '2015-01-01' THEN 'pre2015' WHEN a.SETTLEMENT_ENTERED_DATE < '2017-01-01' THEN '2015-16' ELSE '2017+' END AS ERA,
  COUNT(*) AS N, MIN(a.ACTIVITY_ID) AS MIN_ACT, MAX(a.ACTIVITY_ID) AS MAX_ACT, MAX(TRY_TO_NUMBER(a.ACTIVITY_ID)) AS MAX_ACT_NUM
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS a JOIN f USING (PGM_SYS_ID)
WHERE f.ST = 'NE' GROUP BY 1,2,3,4 ORDER BY 4,5 DESC;
-- [L1-2] ACTIVITY_ID as a clock: national formal actions, activity id range by settlement year (tells whether an undated NE row is recent)
SELECT YEAR(SETTLEMENT_ENTERED_DATE) AS YR, COUNT(*) AS N, MEDIAN(TRY_TO_NUMBER(ACTIVITY_ID)) AS MED_ACT, MIN(TRY_TO_NUMBER(ACTIVITY_ID)) AS MIN_ACT, MAX(TRY_TO_NUMBER(ACTIVITY_ID)) AS MAX_ACT
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS
WHERE SETTLEMENT_ENTERED_DATE >= '2010-01-01' AND SETTLEMENT_ENTERED_DATE < '2027-01-01' GROUP BY 1 ORDER BY 1;
-- [L1-3] Nebraska informal actions by year and type 2012-2025 (did consent orders get keyed as informal?)
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT YEAR(i.ACHIEVED_DATE) AS YR, i.STATE_EPA_FLAG, i.ENF_TYPE_DESC, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS i JOIN f USING (PGM_SYS_ID)
WHERE f.ST = 'NE' AND i.ACHIEVED_DATE >= '2012-01-01' AND i.ACHIEVED_DATE < '2026-01-01' GROUP BY 1,2,3 ORDER BY 1,2,4 DESC;
-- [L1-4] Peer check: states with zero state/local formal actions settled 2017-2025, and formal actions with no settlement date, per state
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1),
m AS (SELECT ST, COUNT_IF(CLS='MAJ' AND OP='OPR') AS MAJ FROM f GROUP BY 1),
a AS (SELECT f.ST, COUNT_IF(a.STATE_EPA_FLAG <> 'E' AND a.SETTLEMENT_ENTERED_DATE >= '2017-01-01' AND a.SETTLEMENT_ENTERED_DATE < '2026-01-01') AS ST_1725,
   COUNT_IF(a.STATE_EPA_FLAG <> 'E' AND a.SETTLEMENT_ENTERED_DATE >= '2005-01-01' AND a.SETTLEMENT_ENTERED_DATE < '2015-01-01') AS ST_0514,
   COUNT_IF(a.SETTLEMENT_ENTERED_DATE IS NULL) AS NODATE, COUNT_IF(a.STATE_EPA_FLAG = 'E' AND a.SETTLEMENT_ENTERED_DATE >= '2017-01-01') AS EPA_17
 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS a JOIN f USING (PGM_SYS_ID) GROUP BY 1)
SELECT m.ST, m.MAJ, a.ST_0514, a.ST_1725, ROUND(a.ST_1725 / NULLIF(m.MAJ,0), 3) AS PER_MAJ_1725, a.NODATE, a.EPA_17
FROM m LEFT JOIN a USING (ST) WHERE m.MAJ >= 30 ORDER BY PER_MAJ_1725 NULLS FIRST LIMIT 15;
-- [L1-5] Second source: ECHO frame for Nebraska air facilities - formal action count (last ~5 yrs, all programs) and last formal date
SELECT HAS_AIR_PROGRAM, HAS_WATER_PROGRAM OR HAS_HAZWASTE_PROGRAM AS OTHER_PGM, COUNT(*) AS N, COUNT_IF(FORMAL_ACTION_COUNT > 0) AS ANY_FORMAL_5Y, SUM(FORMAL_ACTION_COUNT) AS FA_SUM,
  COUNT_IF(DATE_LAST_FORMAL_ACTION >= '2017-01-01') AS LAST_FORMAL_2017, MAX(DATE_LAST_FORMAL_ACTION) AS MAX_LAST_FORMAL
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO WHERE STATE = 'NE' AND IS_ACTIVE AND HAS_AIR_PROGRAM GROUP BY 1,2;
-- [L1-6] Nebraska local agencies: majors and HPVs by local control region (Lincoln-Lancaster, Omaha) since 2015
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, ANY_VALUE(LOCAL_CONTROL_REGION_NAME) AS LCR, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1),
v AS (SELECT PGM_SYS_ID, COUNT_IF(ENF_RESPONSE_POLICY_CODE='HPV') AS HPV, COUNT_IF(ENF_RESPONSE_POLICY_CODE='HPV' AND HPV_RESOLVED_DATE IS NOT NULL) AS HPV_RES, LISTAGG(DISTINCT AGENCY_TYPE_DESC, ';') AS AG
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2015-01-01' GROUP BY 1)
SELECT f.LCR, v.AG, COUNT(*) AS FACS, COUNT_IF(f.CLS='MAJ' AND f.OP='OPR') AS OPR_MAJ, SUM(v.HPV) AS HPV, SUM(v.HPV_RES) AS HPV_RES
FROM f LEFT JOIN v USING (PGM_SYS_ID) WHERE f.ST='NE' GROUP BY 1,2 ORDER BY 3 DESC;
-- [L1-7] Nebraska HPV resolution by day-zero year 2005-2025 (did resolved dates stop at the same time as formal actions?)
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT YEAR(v.HPV_DAYZERO_DATE) AS DZ_YR, COUNT(*) AS HPV, COUNT_IF(v.HPV_RESOLVED_DATE IS NOT NULL) AS RESOLVED, MAX(v.HPV_RESOLVED_DATE) AS LAST_RES,
  COUNT(DISTINCT v.PGM_SYS_ID) AS FACS, COUNT(DISTINCT v.ACTIVITY_ID) AS DIST_ACT
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY v JOIN f USING (PGM_SYS_ID)
WHERE f.ST='NE' AND v.ENF_RESPONSE_POLICY_CODE='HPV' AND v.HPV_DAYZERO_DATE >= '2005-01-01' GROUP BY 1 ORDER BY 1;

-- [L1-8] ECHO says 14 air-only Nebraska facilities had a formal action 2017+; do they have one in ICIS-Air formal actions, and from whom?
WITH e AS (SELECT TO_VARCHAR(FRS_ID) AS REG, FACILITY_NAME, CITY, DATE_LAST_FORMAL_ACTION, FORMAL_ACTION_COUNT, HAS_DRINKING_WATER_PROGRAM
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO WHERE STATE='NE' AND IS_ACTIVE AND HAS_AIR_PROGRAM AND NOT HAS_WATER_PROGRAM AND NOT HAS_HAZWASTE_PROGRAM AND DATE_LAST_FORMAL_ACTION >= '2017-01-01'),
f AS (SELECT PGM_SYS_ID, TO_VARCHAR(ANY_VALUE(REGISTRY_ID)) AS REG FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE STATE='NE' GROUP BY 1),
a AS (SELECT f.REG, LISTAGG(a.STATE_EPA_FLAG || ':' || TO_VARCHAR(a.SETTLEMENT_ENTERED_DATE) || ':' || a.ENF_TYPE_DESC, ' | ') AS ICIS_FORMAL
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS a JOIN f USING (PGM_SYS_ID) WHERE a.SETTLEMENT_ENTERED_DATE >= '2017-01-01' GROUP BY 1)
SELECT e.*, a.ICIS_FORMAL FROM e LEFT JOIN a USING (REG) ORDER BY e.DATE_LAST_FORMAL_ACTION;
-- [L1-9] Current HPV status of Nebraska operating majors vs Iowa and Kansas (neighbors)
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP, ANY_VALUE(CURRENT_HPV) AS HPV FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT ST, HPV, COUNT(*) AS OPR_MAJ FROM f WHERE CLS='MAJ' AND OP='OPR' AND ST IN ('NE','IA','KS','MO','SD') GROUP BY 1,2 ORDER BY 1,3 DESC;

-- [L2-1] Texas evaluations by type and agency, 2015-2025: does TCEQ log its work as partial evaluations instead of full ones?
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT f.ST, e.COMP_MONITOR_TYPE_CODE, e.COMP_MONITOR_TYPE_DESC, e.STATE_EPA_FLAG, COUNT(*) AS N, COUNT(DISTINCT e.PGM_SYS_ID) AS FACS, COUNT_IF(f.CLS='MAJ') AS N_MAJ
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES e JOIN f USING (PGM_SYS_ID)
WHERE f.ST IN ('TX','NM') AND e.ACTUAL_END_DATE >= '2015-01-01' AND e.ACTUAL_END_DATE < '2026-01-01' GROUP BY 1,2,3,4 ORDER BY 1,5 DESC;
-- [L2-2] Programs held by operating majors in TX, NM and all states: is a Title V program open? (class MAJ without an operating Title V permit is a classification question)
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR'),
p AS (SELECT PGM_SYS_ID, MAX(IFF(PROGRAM_CODE='CAATVP' AND AIR_OPERATING_STATUS_CODE='OPR',1,0)) AS TV_OPR, MAX(IFF(PROGRAM_CODE='CAATVP',1,0)) AS TV_ANY, LISTAGG(DISTINCT PROGRAM_CODE, ',') WITHIN GROUP (ORDER BY PROGRAM_CODE) AS PGMS
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_PROGRAMS GROUP BY 1)
SELECT IFF(f.ST IN ('TX','NM'), f.ST, 'OTHER') AS GRP, COUNT(*) AS OPR_MAJ, COUNT_IF(p.TV_OPR=1) AS TV_OPR, COUNT_IF(p.TV_ANY=1) AS TV_ANY, COUNT_IF(p.PGM_SYS_ID IS NULL) AS NO_PGM_ROW
FROM f LEFT JOIN p USING (PGM_SYS_ID) GROUP BY 1 ORDER BY 1;
-- [L2-3] Distinct program codes seen in the programs table (to confirm the Title V code)
SELECT PROGRAM_CODE, PROGRAM_DESC, COUNT(*) AS N FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_PROGRAMS GROUP BY 1,2 ORDER BY 3 DESC LIMIT 20;

-- [L2-4] Rebuild the stale-but-alive majors (no FCE since 2021-07-01, alive by ICIS activity since 2021-07-01 or TRI/GHG/CAMD report 2022+, no sibling major FCE) and split by what keeps them alive, Title V status and recent partial evaluations
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, TO_VARCHAR(ANY_VALUE(REGISTRY_ID)) AS REG FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR'),
ev AS (SELECT PGM_SYS_ID, MAX(IFF(COMP_MONITOR_TYPE_CODE IN ('FOO','FFO'), ACTUAL_END_DATE, NULL)) AS LAST_FCE, MAX(IFF(COMP_MONITOR_TYPE_CODE NOT IN ('FOO','FFO'), ACTUAL_END_DATE, NULL)) AS LAST_PCE
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES WHERE ACTUAL_END_DATE >= '1970-01-01' AND ACTUAL_END_DATE < '2027-01-01' GROUP BY 1),
act AS (SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2021-07-01' AND ACTUAL_END_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2021-07-01' AND ACHIEVED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2021-07-01' AND SETTLEMENT_ENTERED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2021-07-01'),
em AS (SELECT DISTINCT TO_VARCHAR(REGISTRY_ID) AS REG FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS WHERE REPORTING_YEAR >= 2022 AND PGM_SYS_ACRNM IN ('E-GGRT','TRIS','CAMDBS')),
sib AS (SELECT DISTINCT f.REG FROM f JOIN ev USING (PGM_SYS_ID) WHERE ev.LAST_FCE >= '2021-07-01' AND f.REG IS NOT NULL),
tv AS (SELECT PGM_SYS_ID, MAX(IFF(PROGRAM_CODE='CAATVP' AND AIR_OPERATING_STATUS_CODE='OPR',1,0)) AS TV_OPR FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_PROGRAMS GROUP BY 1),
x AS (SELECT f.*, ev.LAST_FCE, ev.LAST_PCE, act.PGM_SYS_ID IS NOT NULL AS ICIS_ALIVE, em.REG IS NOT NULL AS EMIS_ALIVE, sib.REG IS NOT NULL AS SIB, COALESCE(tv.TV_OPR,0) AS TV_OPR
  FROM f LEFT JOIN ev USING (PGM_SYS_ID) LEFT JOIN act USING (PGM_SYS_ID) LEFT JOIN em ON em.REG = f.REG LEFT JOIN sib ON sib.REG = f.REG LEFT JOIN tv USING (PGM_SYS_ID))
SELECT IFF(ST IN ('TX','NM','OH','CA','LA','OK'), ST, 'OTHER') AS GRP, COUNT(*) AS OPR_MAJ,
  COUNT_IF(LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AS STALE,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB) AS STALE_ALIVE,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND ICIS_ALIVE AND NOT SIB) AS ALIVE_BY_ICIS,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND EMIS_ALIVE AND NOT ICIS_ALIVE AND NOT SIB) AS ALIVE_BY_EMIS_ONLY,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB AND TV_OPR=1) AS STALE_ALIVE_TV_OPR,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB AND LAST_PCE >= '2021-07-01') AS STALE_ALIVE_WITH_RECENT_PCE,
  COUNT_IF((LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB AND LAST_FCE IS NULL) AS STALE_ALIVE_NEVER
FROM x GROUP BY 1 ORDER BY 1;

-- [L2-5] Every TX and NM stale-but-alive major, with: any other ICIS-Air ID (any class) at the same registry or same name+city that had an FCE since 2021-07-01 (re-registered or minor permit covering the site), NAICS, alive signal, 2023 GHG
WITH fall AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, TO_VARCHAR(ANY_VALUE(REGISTRY_ID)) AS REG, UPPER(TRIM(ANY_VALUE(FACILITY_NAME))) AS NM, UPPER(TRIM(ANY_VALUE(CITY))) AS CITY, ANY_VALUE(NAICS_CODES) AS NAICS, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE STATE IN ('TX','NM') GROUP BY 1),
f AS (SELECT * FROM fall WHERE CLS='MAJ' AND OP='OPR'),
ev AS (SELECT PGM_SYS_ID, MAX(IFF(COMP_MONITOR_TYPE_CODE IN ('FOO','FFO'), ACTUAL_END_DATE, NULL)) AS LAST_FCE, MAX(ACTUAL_END_DATE) AS LAST_ANY
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES WHERE ACTUAL_END_DATE >= '1970-01-01' AND ACTUAL_END_DATE < '2027-01-01' GROUP BY 1),
act AS (SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2021-07-01' AND ACTUAL_END_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2021-07-01' AND ACHIEVED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2021-07-01' AND SETTLEMENT_ENTERED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2021-07-01'),
em AS (SELECT TO_VARCHAR(REGISTRY_ID) AS REG, SUM(IFF(PGM_SYS_ACRNM='E-GGRT' AND REPORTING_YEAR=2023, TRY_TO_DOUBLE(ANNUAL_EMISSION), 0)) AS GHG23 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS WHERE REPORTING_YEAR >= 2022 AND PGM_SYS_ACRNM IN ('E-GGRT','TRIS','CAMDBS') AND TO_VARCHAR(REGISTRY_ID) IN (SELECT REG FROM fall) GROUP BY 1),
cov AS (SELECT fall.PGM_SYS_ID, fall.REG, fall.NM, fall.CITY, fall.CLS FROM fall JOIN ev USING (PGM_SYS_ID) WHERE ev.LAST_FCE >= '2021-07-01'),
x AS (SELECT f.*, ev.LAST_FCE, ev.LAST_ANY, act.PGM_SYS_ID IS NOT NULL AS ICIS_ALIVE, em.REG IS NOT NULL AS EMIS_ALIVE, em.GHG23,
   (SELECT COUNT(*) FROM cov WHERE cov.REG = f.REG AND cov.PGM_SYS_ID <> f.PGM_SYS_ID AND cov.CLS='MAJ') AS SIB_MAJ,
   (SELECT COUNT(*) FROM cov WHERE cov.REG = f.REG AND cov.PGM_SYS_ID <> f.PGM_SYS_ID) AS SIB_ANY_REG,
   (SELECT COUNT(*) FROM cov WHERE cov.NM = f.NM AND cov.CITY = f.CITY AND cov.PGM_SYS_ID <> f.PGM_SYS_ID) AS SIB_NAME_CITY
  FROM f LEFT JOIN ev USING (PGM_SYS_ID) LEFT JOIN act USING (PGM_SYS_ID) LEFT JOIN em ON em.REG = f.REG)
SELECT PGM_SYS_ID, ST, REG, NM, CITY, LEFT(NAICS,6) AS NAICS, LAST_FCE, LAST_ANY, ICIS_ALIVE, EMIS_ALIVE, ROUND(GHG23) AS GHG23, SIB_ANY_REG, SIB_NAME_CITY
FROM x WHERE (LAST_FCE IS NULL OR LAST_FCE < '2021-07-01') AND (ICIS_ALIVE OR EMIS_ALIVE) AND SIB_MAJ = 0
ORDER BY ST, GHG23 DESC NULLS LAST;

-- [L2-6] Age check on the 259 TX+NM stale-but-alive majors (ids from L2-5): earliest program begin date; a major that began after mid-2021 is not 5 years overdue
WITH p AS (SELECT PGM_SYS_ID, MIN(TRY_TO_DATE(LEFT(BEGIN_DATE,10))) AS BEGIN_MIN, MIN(BEGIN_DATE) AS BEGIN_RAW, COUNT_IF(BEGIN_DATE IS NULL OR BEGIN_DATE='') AS NO_BEGIN
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_PROGRAMS WHERE PGM_SYS_ID IN ('NM0000003502900013','NM0000003502300007','NM0000003501500011','NM0000003502501451','NM0000003501500024','NM0000003501501662','NM0000003504900032','NM0000003501500467','NM0000003504100014','NM0000003500500008','NM0000003504500419','NM0000003503100008','NM0000003502500060','NM0000003503500013','NM0000003501508066','NM0000003501300021','NM0000003502500035','NM0000003501502791','NM0000003502501996','NM0000003502500113','NM0000003503900003','NM0000003500900014','NM0000003502501285','NM0000003501501435','NM0000003501502792','NM0000003502500571','NM0000003506100039','NM0000003502500061','NM0000003501501863','NM0000003501502010','NM0000003502500145','NM0000003502501281','NM0000003501501779','TX0000004816700116','TX0000004836100063','TX0000004809100006','TX0000004807100037','TX0000004829700057','TX0000004829700006','TX0000004824500710','TX0000004818100073','TX0000004820102077','TX0000004824500711','TX0000004807300026','TX0000004848500046','TX0000004806100202','TX0000004840100660','TX0000004800500034','TX0000004820100477','TX0000004823100029','TX0000004837500687','TX0000004804100646','TX0000004813900676','TX0000004827700252','TX0000004807100085','TX0000004811300952','TX0000004834700034','TX0000004844900020','TX0000004835500693','TX0000004842300234','TX0000004820101528','TX0000004836700155','TX0000004830900054','TX0000004830900075','TX0000004808500208','TX0000004824500008','TX0000004837300677','TX0000004835501656','TX0000004803700036','TX0000004813900058','TX0000004841500095','TX0000004814100100','TX0000004820100177','TX0000004827700249','TX0000004843900287','TX0000004820101510','TX0000004820100446','TX0000004846900033','TX0000004821500649','TX0000004823100036','TX0000004848300261','TX0000004829300020','TX0000004836500086','TX0000004821500088','TX0000004811300844','TX0000004811300979','TX0000004843900574','TX0000004802900619','TX0000004843900687','TX0000004820101285','TX00000