ev AS (SELECT PGM_SYS_ID, MAX(IFF(COMP_MONITOR_TYPE_CODE IN ('FOO','FFO'), ACTUAL_END_DATE, NULL)) AS LAST_FCE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES WHERE PGM_SYS_ID IN ('NM0000003502900013','NM0000003502300007','NM0000003501500011','NM0000003502501451','NM0000003501500024','NM0000003501501662','NM0000003504900032','NM0000003501500467','NM0000003504100014','NM0000003500500008','NM0000003504500419','NM0000003503100008','NM0000003502500060','NM0000003503500013','NM0000003501508066','NM0000003501300021','NM0000003502500035','NM0000003501502791','NM0000003502501996','NM0000003502500113','NM0000003503900003','NM0000003500900014','NM0000003502501285','NM0000003501501435','NM0000003501502792','NM0000003502500571','NM0000003506100039','NM0000003502500061','NM0000003501501863','NM0000003501502010','NM0000003502500145','NM0000003502501281','NM0000003501501779','TX0000004816700116','TX0000004836100063','TX0000004809100006','TX0000004807100037','TX0000004829700057','TX0000004829700006','TX0000004824500710','TX0000004818100073','TX0000004820102077','TX0000004824500711','TX0000004807300026','TX0000004848500046','TX0000004806100202','TX0000004840100660','TX0000004800500034','TX0000004820100477','TX0000004823100029','TX0000004837500687','TX0000004804100646','TX0000004813900676','TX0000004827700252','TX0000004807100085','TX0000004811300952','TX0000004834700034','TX0000004844900020','TX0000004835500693','TX0000004842300234','TX0000004820101528','TX0000004836700155','TX0000004830900054','TX0000004830900075','TX0000004808500208','TX0000004824500008','TX0000004837300677','TX0000004835501656','TX0000004803700036','TX0000004813900058','TX0000004841500095','TX0000004814100100','TX0000004820100177','TX0000004827700249','TX0000004843900287','TX0000004820101510','TX0000004820100446','TX0000004846900033','TX0000004821500649','TX0000004823100036','TX0000004848300261','TX0000004829300020','TX0000004836500086','TX0000004821500088','TX0000004811300844','TX0000004811300979','TX0000004843900574','TX0000004802900619','TX0000004843900687','TX0000004820101285','TX0000004820102085','TX0000004820101811','TX0000004820101297','TX0000004820102005','TX0000004845100022','TX0000004813900025','TX0000004833900016','TX0000004825100174','TX0000004816700472','TX0000004811300225','TX0000004806100220','TX0000004847100022','TX0000004833900004','TX0000004802900713','TX0000004820101754','TX0000004811300236','TX0000004820100321','TX0000004811300731','TX0000004820101384','TX0000004824100004','TX0000004815700003','TX0000004820101849','TX0000004817300144','TX0000004843900545','TX0000004820102020','TX0000004824500691','TX0000004803900032','TX0000004802700669','TX0000004820101996','TX0000004818700026','TX0000004824500163','TX0000004846100055','TX0000004813500071','TX0000004843900279','TX0000004820101291','TX0000004825100064','TX0000004843900688','TX0000004825700023','TX0000004820300011','TX0000004807100017','TX0000004820100359','TX0000004820101561','TX0000004818300010','TX0000004813900048','TX0000004843901772','TX0000004836300031','TX0000004816700153','TX0000004803700001','TX0000004803700021','TX0000004820100382','TX0000004819900002','TX0000004813901672','TX0000004824500712','TX0000004845300460','TX0000004814300015','TX0000004834300008','TX0000004843901705','TX0000004824500003','TX0000004820100052','TX0000004811301005','TX0000004811300917','TX0000004820100187','TX0000004820100818','TX0000004800500015','TX0000004836100249','TX0000004848500045','TX0000004802900714','TX0000004811300930','TX0000004813300012','TX0000004812100285','TX0000004803900038','TX0000004803900139','TX0000004800500005','TX0000004814100692','TX0000004820100886','TX0000004841900015','TX0000004825100065','TX0000004827700005','TX0000004820101507','TX0000004843900318','TX0000004811300418','TX0000004820101617','TX0000004800500030','TX0000004801500036','TX0000004848100315','TX0000004831700523','TX0000004836500070','TX0000004849700013','TX0000004818900034','TX0000004838300003','TX0000004836700002','TX0000004827300017','TX0000004831700285','TX0000004825500286','TX0000004828700003','TX0000004801500021','TX0000004816300003','TX0000004830300669','TX0000004849700740','TX0000004838902569','TX0000004808500212','TX0000004821300121','TX0000004820101295','TX0000004825500189','TX0000004815700016','TX0000004807100049','TX0000004820100546','TX0000004843901732','TX0000004813700015','TX0000004830100167','TX0000004849700065','TX0000004830100020','TX0000004838902272','TX0000004825500176','TX0000004820101956','TX0000004825500187','TX0000004840900003','TX0000004821100034','TX0000004849700827','TX0000004809700033','TX0000004849500022','TX0000004803900002','TX0000004806500044','TX0000004840900250','TX0000004825500186','TX0000004834900653','TX0000004811300859','TX0000004838902579','TX0000004831700283','TX0000004833700225','TX0000004825500167','TX0000004825500010','TX0000004810300010','TX0000004831700239','TX0000004821300004','TX0000004817900154','TX0000004843901710','TX0000004831700306','TX0000004827700019','TX0000004848100021','TX0000004820100164','TX0000004818700019','TX0000004820100078','TX0000004820300099','TX0000004820101558','TX0000004829700014','TX0000004834100059','TX0000004830100188','TX0000004836300004','TX0000004802900641','TX0000004816100635','TX0000004816100033','TX0000004849700019','TX0000004818300106','TX0000004807100147','TX0000004807100134','TX0000004820100178','TX0000004802900069','TX0000004849500080','TX0000004847500009','TX0000004820100110','TX0000004820102061','TX0000004842300002','TX0000004830100023','TX0000004802900023','TX0000004818100056','TX0000004830100017','TX0000004825500181','TX0000004838300036') GROUP BY 1)
SELECT LEFT(PGM_SYS_ID,2) AS ST, ev.LAST_FCE IS NULL AS NEVER_FCE,
  COUNT(*) AS N, COUNT_IF(p.BEGIN_MIN >= '2021-07-01') AS BEGAN_AFTER_2021_07, COUNT_IF(p.BEGIN_MIN >= '2016-01-01') AS BEGAN_AFTER_2016, COUNT_IF(p.BEGIN_MIN IS NULL) AS NO_BEGIN_DATE,
  MIN(p.BEGIN_RAW) AS MIN_RAW, MAX(p.BEGIN_RAW) AS MAX_RAW
FROM p LEFT JOIN ev USING (PGM_SYS_ID) GROUP BY 1,2 ORDER BY 1,2;

-- [L2-7] Praxair Texas City (no ICIS evaluation ever, 1.29M t CO2e by registry): is the plant evaluated under another ICIS-Air record in Texas City?
WITH ev AS (SELECT PGM_SYS_ID, MAX(IFF(COMP_MONITOR_TYPE_CODE IN ('FOO','FFO'), ACTUAL_END_DATE, NULL)) AS LAST_FCE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES GROUP BY 1)
SELECT f.PGM_SYS_ID, f.REGISTRY_ID, f.FACILITY_NAME, f.STREET_ADDRESS, f.AIR_POLLUTANT_CLASS_CODE, f.AIR_OPERATING_STATUS_CODE, f.NAICS_CODES, ev.LAST_FCE
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES f LEFT JOIN ev USING (PGM_SYS_ID)
WHERE f.STATE='TX' AND UPPER(f.CITY) IN ('TEXAS CITY','LA PORTE') AND (UPPER(f.FACILITY_NAME) LIKE '%PRAXAIR%' OR UPPER(f.FACILITY_NAME) LIKE '%LINDE%');

-- [L2-8] Per-state rebuild with the two fixes: drop majors whose earliest program begin date is after 2021-07-01 (too new to be 5 yrs overdue); strict version also requires ICIS activity, not just a registry-level emissions report
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, TO_VARCHAR(ANY_VALUE(REGISTRY_ID)) AS REG FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR'),
ev AS (SELECT PGM_SYS_ID, MAX(ACTUAL_END_DATE) AS LAST_FCE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FCES_PCES WHERE COMP_MONITOR_TYPE_CODE IN ('FOO','FFO') AND ACTUAL_END_DATE >= '1970-01-01' AND ACTUAL_END_DATE < '2027-01-01' GROUP BY 1),
act AS (SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2021-07-01' AND ACTUAL_END_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2021-07-01' AND ACHIEVED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2021-07-01' AND SETTLEMENT_ENTERED_DATE < '2027-01-01'
  UNION SELECT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2021-07-01'),
em AS (SELECT DISTINCT TO_VARCHAR(REGISTRY_ID) AS REG FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS WHERE REPORTING_YEAR >= 2022 AND PGM_SYS_ACRNM IN ('E-GGRT','TRIS','CAMDBS')),
sib AS (SELECT DISTINCT f.REG FROM f JOIN ev USING (PGM_SYS_ID) WHERE ev.LAST_FCE >= '2021-07-01' AND f.REG IS NOT NULL),
p AS (SELECT PGM_SYS_ID, MIN(TRY_TO_DATE(BEGIN_DATE, 'MM/DD/YYYY')) AS BEGIN_MIN FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_PROGRAMS GROUP BY 1),
x AS (SELECT f.ST, (ev.LAST_FCE IS NULL OR ev.LAST_FCE < '2021-07-01') AS STALE, act.PGM_SYS_ID IS NOT NULL AS ICIS_ALIVE, em.REG IS NOT NULL AS EMIS_ALIVE, sib.REG IS NOT NULL AS SIB, COALESCE(p.BEGIN_MIN < '2021-07-01', TRUE) AS OLD_ENOUGH
  FROM f LEFT JOIN ev USING (PGM_SYS_ID) LEFT JOIN act USING (PGM_SYS_ID) LEFT JOIN em ON em.REG=f.REG LEFT JOIN sib ON sib.REG=f.REG LEFT JOIN p USING (PGM_SYS_ID)),
s AS (SELECT ST, COUNT(*) AS MAJ,
  COUNT_IF(STALE AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB) AS ORIG,
  COUNT_IF(STALE AND (ICIS_ALIVE OR EMIS_ALIVE) AND NOT SIB AND OLD_ENOUGH) AS AGE_FIX,
  COUNT_IF(STALE AND ICIS_ALIVE AND NOT SIB AND OLD_ENOUGH) AS STRICT
 FROM x GROUP BY 1 HAVING COUNT(*) >= 30)
SELECT ST, MAJ, ORIG, ROUND(100*ORIG/MAJ,1) AS ORIG_P100, AGE_FIX, ROUND(100*AGE_FIX/MAJ,1) AS AGE_P100, STRICT, ROUND(100*STRICT/MAJ,1) AS STRICT_P100,
  MEDIAN(100*ORIG/MAJ) OVER () AS MED_ORIG, MEDIAN(100*AGE_FIX/MAJ) OVER () AS MED_AGE, MEDIAN(100*STRICT/MAJ) OVER () AS MED_STRICT,
  RANK() OVER (ORDER BY STRICT/MAJ DESC) AS RK_STRICT
FROM s ORDER BY STRICT_P100 DESC LIMIT 12;

-- [L3-1] Stack test status codes since 2015, Iowa vs everyone: rows, distinct activity ids, distinct facility-days
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT IFF(f.ST='IA','IA','ALL_OTHER') AS GRP, s.AIR_STACK_TEST_STATUS_CODE, s.AIR_STACK_TEST_STATUS_DESC, s.STATE_EPA_FLAG, COUNT(*) AS ROWS_, COUNT(DISTINCT s.ACTIVITY_ID) AS ACTS, COUNT(DISTINCT s.PGM_SYS_ID || TO_VARCHAR(s.ACTUAL_END_DATE)) AS FAC_DAYS
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS s JOIN f USING (PGM_SYS_ID)
WHERE s.ACTUAL_END_DATE >= '2015-01-01' AND s.ACTUAL_END_DATE < '2027-01-01' GROUP BY 1,2,3,4 ORDER BY 1,5 DESC;
-- [L3-2] Grain Processing Corp: every ICIS-Air record by that name, with lifetime formal actions (dated and undated), informal since 2015, and stack fails counted three ways
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(REGISTRY_ID) AS REG, ANY_VALUE(FACILITY_NAME) AS NM, ANY_VALUE(CITY) AS CITY, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE UPPER(FACILITY_NAME) LIKE '%GRAIN PROCESSING%' OR (STATE='IA' AND UPPER(CITY)='MUSCATINE' AND UPPER(FACILITY_NAME) LIKE 'GPC%') GROUP BY 1),
fa AS (SELECT PGM_SYS_ID, LISTAGG(STATE_EPA_FLAG || ':' || COALESCE(TO_VARCHAR(SETTLEMENT_ENTERED_DATE),'nodate') || ':' || ENF_TYPE_DESC || ':$' || COALESCE(TO_VARCHAR(PENALTY_AMOUNT),'-'), ' | ') WITHIN GROUP (ORDER BY SETTLEMENT_ENTERED_DATE) AS FORMALS
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
inf AS (SELECT PGM_SYS_ID, COUNT(*) AS INF_15, LISTAGG(DISTINCT ENF_TYPE_DESC, ';') AS INF_TYPES FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
st AS (SELECT PGM_SYS_ID, COUNT_IF(AIR_STACK_TEST_STATUS_CODE='FAI') AS FAIL_ROWS, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTIVITY_ID, NULL)) AS FAIL_ACTS,
   COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTUAL_END_DATE, NULL)) AS FAIL_DAYS, COUNT(DISTINCT ACTIVITY_ID) AS ALL_ACTS, COUNT(DISTINCT ACTUAL_END_DATE) AS ALL_DAYS,
   COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', YEAR(ACTUAL_END_DATE), NULL)) AS FAIL_YEARS, LISTAGG(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', POLLUTANT_CODES, NULL), ';') AS FAIL_POLS
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2015-01-01' AND ACTUAL_END_DATE < '2027-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1)
SELECT f.*, st.FAIL_ROWS, st.FAIL_ACTS, st.FAIL_DAYS, st.ALL_ACTS, st.ALL_DAYS, st.FAIL_YEARS, st.FAIL_POLS, inf.INF_15, inf.INF_TYPES, fa.FORMALS
FROM f LEFT JOIN st USING (PGM_SYS_ID) LEFT JOIN inf USING (PGM_SYS_ID) LEFT JOIN fa USING (PGM_SYS_ID);
-- [L3-3] Grain Processing Corp fail days: rows per day, pollutants, and whether the same pollutant passed the same day or within 180 days
WITH st AS (SELECT s.PGM_SYS_ID, s.ACTIVITY_ID, s.ACTUAL_END_DATE AS D, COALESCE(s.POLLUTANT_CODES,'') AS POL, s.AIR_STACK_TEST_STATUS_CODE AS S
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS s JOIN (SELECT DISTINCT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE STATE='IA' AND UPPER(FACILITY_NAME) LIKE '%GRAIN PROCESSING%') g USING (PGM_SYS_ID)
  WHERE s.ACTUAL_END_DATE >= '2015-01-01')
SELECT YEAR(fl.D) AS YR, COUNT(*) AS FAIL_ROWS, COUNT(DISTINCT fl.D) AS FAIL_DAYS, LISTAGG(DISTINCT fl.POL, ';') AS POLS,
  COUNT_IF(EXISTS (SELECT 1 FROM st p WHERE p.PGM_SYS_ID=fl.PGM_SYS_ID AND p.POL=fl.POL AND p.S='PSS' AND p.D > fl.D AND p.D <= DATEADD(day,180,fl.D))) AS RETEST_PASS_180
FROM st fl WHERE fl.S='FAI' GROUP BY 1 ORDER BY 1;

-- [L3-4] Per state: facilities with 3+ distinct fail DAYS since 2015 (not rows) and the share with no formal action since 2015, next to the baseline share of all operating majors with no formal action since 2015
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(STATE) AS ST, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1),
st AS (SELECT PGM_SYS_ID, COUNT(DISTINCT ACTUAL_END_DATE) AS FAIL_DAYS, COUNT(*) AS FAIL_ROWS FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE AIR_STACK_TEST_STATUS_CODE='FAI' AND ACTUAL_END_DATE >= '2015-01-01' AND ACTUAL_END_DATE < '2027-01-01' GROUP BY 1),
fa AS (SELECT DISTINCT PGM_SYS_ID FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2015-01-01' AND SETTLEMENT_ENTERED_DATE < '2027-01-01'),
x AS (SELECT f.ST, f.CLS, f.OP, COALESCE(st.FAIL_DAYS,0) AS FD, COALESCE(st.FAIL_ROWS,0) AS FR, fa.PGM_SYS_ID IS NOT NULL AS HAS_FA FROM f LEFT JOIN st USING (PGM_SYS_ID) LEFT JOIN fa USING (PGM_SYS_ID)),
s AS (SELECT ST,
  COUNT_IF(FR >= 3) AS REP_ROWS, COUNT_IF(FR >= 3 AND NOT HAS_FA) AS REP_ROWS_NOFA,
  COUNT_IF(FD >= 3) AS REP_DAYS, COUNT_IF(FD >= 3 AND NOT HAS_FA) AS REP_DAYS_NOFA,
  COUNT_IF(CLS='MAJ' AND OP='OPR') AS MAJ, COUNT_IF(CLS='MAJ' AND OP='OPR' AND NOT HAS_FA) AS MAJ_NOFA,
  COUNT_IF(CLS='MAJ' AND OP='OPR' AND FD = 0) AS MAJ_NOFAIL, COUNT_IF(CLS='MAJ' AND OP='OPR' AND FD = 0 AND HAS_FA) AS MAJ_NOFAIL_FA
 FROM x GROUP BY 1)
SELECT ST, REP_ROWS, REP_ROWS_NOFA, ROUND(100*REP_ROWS_NOFA/NULLIF(REP_ROWS,0),1) AS PCT_ROWS, REP_DAYS, REP_DAYS_NOFA, ROUND(100*REP_DAYS_NOFA/NULLIF(REP_DAYS,0),1) AS PCT_DAYS,
  MAJ, ROUND(100*MAJ_NOFA/NULLIF(MAJ,0),1) AS PCT_MAJ_NO_FA, ROUND(100*MAJ_NOFAIL_FA/NULLIF(MAJ_NOFAIL,0),1) AS PCT_NONFAILER_MAJ_WITH_FA,
  MEDIAN(IFF(REP_DAYS >= 5, 100*REP_DAYS_NOFA/REP_DAYS, NULL)) OVER () AS MED_PCT_DAYS_5PLUS,
  MEDIAN(IFF(MAJ >= 30, 100*MAJ_NOFA/MAJ, NULL)) OVER () AS MED_PCT_MAJ_NO_FA
FROM s WHERE REP_DAYS >= 5 ORDER BY PCT_DAYS DESC LIMIT 14;
